document.getElementById("form-contato").addEventListener("submit",async e=>{e.preventDefault();const f=e.currentTarget,m=document.getElementById("contacto-msg"),b=f.querySelector("button");m.textContent="A enviar...";b.disabled=true;try{await apiFetch("/publico/contactos",{method:"POST",body:JSON.stringify({nome:document.getElementById("contacto-nome").value,email:document.getElementById("contacto-email").value,assunto:document.getElementById("contacto-assunto").value,mensagem:document.getElementById("contacto-mensagem").value})});m.textContent="Mensagem enviada. A nossa equipa responderá em menos de 24h úteis.";f.reset()}catch(err){m.textContent=err.message}finally{b.disabled=false}});
